import { test, expect } from '@playwright/test';

test.describe('Page Title Navigation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com');
  });

  test('should update page title when navigating to Home section', async ({ page }) => {
    // Click on Home navigation link
    const homeLink = page.getByRole('link', { name: /home/i });
    await homeLink.click();

    // Verify page title updates to Home
    await expect(page).toHaveTitle(/home/i);
  });

  test('should update page title when navigating to About section', async ({ page }) => {
    // Click on About navigation link
    const aboutLink = page.getByRole('link', { name: /about/i });
    await aboutLink.click();

    // Verify page title updates to About
    await expect(page).toHaveTitle(/about/i);
  });

  test('should update page title when navigating to Services section', async ({ page }) => {
    // Click on Services navigation link
    const servicesLink = page.getByRole('link', { name: /services/i });
    await servicesLink.click();

    // Verify page title updates to Services
    await expect(page).toHaveTitle(/services/i);
  });

  test('should update page title when navigating to Contact section', async ({ page }) => {
    // Click on Contact navigation link
    const contactLink = page.getByRole('link', { name: /contact/i });
    await contactLink.click();

    // Verify page title updates to Contact
    await expect(page).toHaveTitle(/contact/i);
  });

  test('should maintain correct title when navigating between multiple sections', async ({ page }) => {
    // Navigate to About section
    const aboutLink = page.getByRole('link', { name: /about/i });
    await aboutLink.click();
    await expect(page).toHaveTitle(/about/i);

    // Navigate to Services section
    const servicesLink = page.getByRole('link', { name: /services/i });
    await servicesLink.click();
    await expect(page).toHaveTitle(/services/i);

    // Navigate back to Home section
    const homeLink = page.getByRole('link', { name: /home/i });
    await homeLink.click();
    await expect(page).toHaveTitle(/home/i);
  });

  test('should update page title when using navigation buttons', async ({ page }) => {
    // Click next button to navigate to next section
    const nextButton = page.getByRole('button', { name: /next/i });
    await nextButton.click();

    // Verify page title has updated
    const pageTitle = await page.title();
    expect(pageTitle).toBeTruthy();
    expect(pageTitle.length).toBeGreaterThan(0);
  });
});
